"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";
import { plane } from "./three/Plane";
import { buildingMaterial } from "./three/Materials";
import { createCamera } from "./three/Camera";
import { controls } from "./three/Controls";

export default function ThreeScene({ settings }) {
  const ref = useRef(null);
  const cameraRef = useRef(null);
  const controlsRef = useRef(null);
  const cubeRef = useRef(null);
  const rendererRef = useRef(null);
  const sceneRef = useRef(null);

  useEffect(() => {
    const container = ref.current;
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(container.clientWidth, container.clientHeight);
    container.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const camera = createCamera(container.clientWidth, container.clientHeight);
    cameraRef.current = camera;

    const scene = new THREE.Scene();
    sceneRef.current = scene;

    const cube = new THREE.Mesh(new THREE.BoxGeometry(), buildingMaterial);
    scene.add(cube);
    cubeRef.current = cube;

    plane.rotation.x = -Math.PI / 2;
    plane.position.y = -0.5;
    scene.add(plane);

    const light = new THREE.DirectionalLight(0xffffff, 1);
    light.position.set(2, 2, 2);
    scene.add(light);

    let frame;
    const loop = () => {
      cube.rotation.x += 0.01;
      cube.rotation.y += 0.01;

      controls.update();
      renderer.render(scene, camera);
      frame = requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener("resize", handleResize);
      container.removeChild(renderer.domElement);
      renderer.dispose();
      cube.geometry.dispose();
      buildingMaterial.dispose();
      controls.dispose();
    };
  }, []);

  useEffect(() => {
    if (cameraRef.current) {
      const minY = 5;
      const maxY = 50;
      cameraRef.current.position.y =
        minY + (maxY - minY) * ((settings.zoom - 1) / 9);
      cameraRef.current.updateProjectionMatrix();
    }
  }, [settings.zoom]);

  return <div ref={ref} className="w-full h-full bg-blue" />;
}
